# Kaggle kernel generated by repro/kgl/dispatch.py — do not edit by hand.
# Runs a shard of paperproto jobs on all visible GPUs (one job per GPU), writes everything
# under /kaggle/working/runs/paperproto so it becomes the kernel output.
import base64, io, json, os, shutil, subprocess, sys, tarfile, time
from pathlib import Path

CFG = json.loads(r'''__CFG__''')
JOBS = json.loads(r'''__JOBS__''')
CODE_B64 = '__CODE_B64__'

T0 = time.time()
BUDGET = CFG.get('budget_s', 11 * 3600)          # stop launching / kill before Kaggle's 12 h cap
ROOT = Path('/kaggle/temp/repro'); ROOT.mkdir(parents=True, exist_ok=True)
WORK = Path('/kaggle/working'); RUNS = WORK / 'runs' / 'paperproto'; RUNS.mkdir(parents=True, exist_ok=True)
LOGS = WORK / 'logs'; LOGS.mkdir(exist_ok=True)


def log(*a):
    print(f'[{(time.time() - T0) / 60:7.1f} min]', *a, flush=True)


# ---- code
with tarfile.open(fileobj=io.BytesIO(base64.b64decode(CODE_B64)), mode='r:gz') as t:
    t.extractall(ROOT)
# utils/util.py imports bm3d.gaussian_kernel at module load (only used for image correlated noise).
try:
    import bm3d  # noqa: F401
except ImportError:
    r = subprocess.run([sys.executable, '-m', 'pip', 'install', '-q', 'bm3d==3.0.7'], capture_output=True, text=True)
    log('pip install bm3d:', 'ok' if r.returncode == 0 else 'failed -> stub')
    if r.returncode:
        (ROOT / 'bm3d.py').write_text(
            'def gaussian_kernel(*a, **k):\n    raise NotImplementedError("bm3d unavailable on this kernel (seismic runs never need it)")\n'
            'def bm3d(*a, **k):\n    raise NotImplementedError("bm3d unavailable")\n')
(ROOT / 'runs').mkdir(exist_ok=True)
if not (ROOT / 'runs' / 'paperproto').exists():
    os.symlink(RUNS, ROOT / 'runs' / 'paperproto')

# ---- data: a seis.tar (or a seis/ folder) somewhere under /kaggle/input
inp = Path('/kaggle/input')
# Kaggle auto-extracts uploaded tars into folders; handle both forms. Data is copied (writable:
# prepare_seismic fixed:* writes new arrays and updates meta.json).
SEISD = ROOT / 'data' / 'seis'; SEISD.mkdir(parents=True, exist_ok=True)
for tf in sorted(inp.rglob('seis*.tar')):
    log('extracting', tf)
    with tarfile.open(tf) as t:
        t.extractall(ROOT / 'data')
for meta in sorted(inp.rglob('seis/*/meta.json')):
    if not (SEISD / meta.parent.name / 'meta.json').exists():
        shutil.copytree(meta.parent, SEISD / meta.parent.name, dirs_exist_ok=True)
if not any(SEISD.iterdir()):
    sys.exit('no seismic data found under /kaggle/input')
for tf in sorted(inp.rglob('prior_runs.tar')):   # earlier joint-corpus weights (HF) for cross evaluation
    with tarfile.open(tf) as t:
        t.extractall(WORK)
for cfg in sorted(inp.rglob('runs/paperproto/*/config.json')):
    if 'prior_runs' in str(cfg) and not (RUNS / cfg.parent.name / 'weights.pth').exists():
        shutil.copytree(cfg.parent, RUNS / cfg.parent.name, dirs_exist_ok=True)
log('prior runs:', sorted(p.name for p in RUNS.iterdir()))
log('data keys:', sorted(p.name for p in (ROOT / 'data' / 'seis').iterdir()))

# ---- resume: copy run folders from earlier kernels attached as kernel_sources
mine = {j['done_file'].split('/')[2] for j in JOBS}
for d in sorted(inp.glob('*/runs/paperproto/*')):
    if d.is_dir() and d.name in mine and not (RUNS / d.name / 'training_summary.json').exists():
        shutil.copytree(d, RUNS / d.name, dirs_exist_ok=True)
        log('carried over from previous kernel:', d.name)

# ---- GPUs
try:
    out = subprocess.run(['nvidia-smi', '-L'], capture_output=True, text=True).stdout
except FileNotFoundError:
    out = ''
gpus = list(range(len([l for l in out.splitlines() if l.startswith('GPU')])))
if not gpus:
    (WORK / 'shard_state.json').write_text(json.dumps(dict(error='no GPU on this kernel (account not GPU-verified?)')))
    sys.exit('NO GPU: refusing to train on CPU')
log('GPUs:', out.strip())

env0 = dict(os.environ, PYTHONUNBUFFERED='1', **CFG.get('env', {}))
done = lambda j: (ROOT / j['done_file']).exists()
running, tries, failed = {}, {}, set()
while True:
    for jid, (p, g, fh) in list(running.items()):
        if p.poll() is None:
            continue
        fh.close(); del running[jid]
        j = next(x for x in JOBS if x['id'] == jid)
        if done(j):
            log('finished', jid)
        else:
            tries[jid] = tries.get(jid, 0) + 1
            log(f'FAILED rc={p.returncode}', jid, f'try {tries[jid]}/3')
            if tries[jid] >= 3:
                failed.add(jid)
    over = time.time() - T0 > BUDGET
    if over and running:
        log('time budget reached: stopping running jobs (latest.pt is saved every 1k steps)')
        for jid, (p, g, fh) in running.items():
            p.terminate()
        for jid, (p, g, fh) in running.items():
            try:
                p.wait(120)
            except subprocess.TimeoutExpired:
                p.kill()
            fh.close()
        running.clear()
    ids_done = {j['id'] for j in JOBS if done(j)}
    pending = [j for j in JOBS if j['id'] not in ids_done and j['id'] not in running and j['id'] not in failed
               and all(d in ids_done for d in j['deps'])]
    if over or (not pending and not running):
        break
    free = [g for g in gpus if g not in {v[1] for v in running.values()}]
    late = time.time() - T0 > CFG.get('no_train_after_s', 1e9)
    if late:   # too late to finish a 50k-step run before the deadline: only evals/preps may start
        pending = [j for j in pending if 'pp_train.py' not in ' '.join(j['cmd'])]
        if not pending and not running:
            break
    while pending and free:
        j, g = pending.pop(0), free.pop(0)
        env = dict(env0, **j.get('env', {}))
        if g is not None:
            env['CUDA_VISIBLE_DEVICES'] = str(g)
        fh = open(LOGS / f"{j['id']}.log", 'a')
        fh.write(f"\n=== start {j['cmd']} on GPU {g}\n"); fh.flush()
        running[j['id']] = (subprocess.Popen(j['cmd'], cwd=ROOT, env=env, stdout=fh, stderr=subprocess.STDOUT), g, fh)
        log('started', j['id'], 'on GPU', g)
    time.sleep(15)

state = dict(done=sorted(j['id'] for j in JOBS if done(j)), failed=sorted(failed),
             unfinished=sorted(j['id'] for j in JOBS if not done(j)), tries=tries,
             elapsed_min=round((time.time() - T0) / 60, 1), gpus=out.strip(), shard=CFG.get('shard'))
(WORK / 'shard_state.json').write_text(json.dumps(state, indent=1))
log('shard state:', json.dumps(state))
# drop the step snapshots of unfinished runs? no: keep everything; outputs are small (~25 MB/run)
